function dslTrim(s)
  s = tostring(s or "")
  return (s:gsub("^%s+", ""):gsub("%s+$", ""))
end

function dslKey(s)
  s = dslTrim(s)
  s = s:gsub("^%[", ""):gsub("%]$", ""):gsub("^%(", ""):gsub("%)$", "")
  s = s:gsub("%s+", "_")
  return string.lower(s)
end

function dslIsIgnoredTerm(term)
  term = dslTrim(term or "")
  if term == "" then return false end
  local ignored = (DSL_COLOR_DB and DSL_COLOR_DB.ignored) or {}
  return ignored[term] == true or ignored[string.lower(term)] == true or ignored[dslKey(term)] == true
end


function dslStripBrackets(s)
  s = dslTrim(s)
  s = s:gsub("^%[", ""):gsub("%]$", "")
  s = s:gsub("^%(", ""):gsub("%)$", "")
  return dslTrim(s)
end

function dslNowRecord()
  local r = { real = os.time(), stamp = os.date("%Y-%m-%d %H:%M:%S") }
  if gmcp then
    if gmcp.tick and gmcp.tick.time then r.game_time = gmcp.tick.time end
    if (not r.game_time) and gmcp.login_data and gmcp.login_data.time then r.game_time = gmcp.login_data.time end
    if gmcp.room_data and gmcp.room_data.room then r.room = gmcp.room_data.room end
    if gmcp.login_data and gmcp.login_data.name then r.character = gmcp.login_data.name end
  end
  return r
end

function dslColorSerializeValue(v, depth, seen)
  depth = depth or 0
  seen = seen or {}
  local tv = type(v)
  if tv == "nil" then return "nil" end
  if tv == "number" or tv == "boolean" then return tostring(v) end
  if tv == "string" then return string.format("%q", v) end
  if tv ~= "table" then return "nil" end
  if seen[v] then return "nil" end
  seen[v] = true
  local indent = string.rep("  ", depth)
  local nextIndent = string.rep("  ", depth + 1)
  local parts = {"{"}
  local keys = {}
  for k,_ in pairs(v) do table.insert(keys, k) end
  table.sort(keys, function(a,b) return tostring(a) < tostring(b) end)
  for _, k in ipairs(keys) do
    local val = v[k]
    local keyText
    if type(k) == "string" and k:match("^[A-Za-z_][A-Za-z0-9_]*$") then keyText = k else keyText = "[" .. dslColorSerializeValue(k, depth + 1, seen) .. "]" end
    table.insert(parts, "\n" .. nextIndent .. keyText .. " = " .. dslColorSerializeValue(val, depth + 1, seen) .. ",")
  end
  table.insert(parts, "\n" .. indent .. "}")
  seen[v] = nil
  return table.concat(parts)
end

function dslColorSave()
  local ok, err = pcall(function()
    local f, ferr = io.open(DSL_COLOR_DATA_PATH, "w")
    if not f then error(ferr or "could not open data file for writing") end
    f:write("return ")
    f:write(dslColorSerializeValue(DSL_COLOR_DB))
    f:write("\n")
    f:close()
  end)
  DSL_COLOR_LAST_SAVE = { ok = ok, error = err, path = DSL_COLOR_DATA_PATH, stamp = os.date("%Y-%m-%d %H:%M:%S") }
  return ok, err
end

function dslColorLoad()
  local loaded = false
  local loadedPath = nil
  local path = DSL_COLOR_DATA_PATH
  local f = io.open(path, "r")
  if f then
    f:close()
    local chunk, lerr = loadfile(path)
    if chunk then
      local ok, data = pcall(chunk)
      if ok and type(data) == "table" then DSL_COLOR_DB = data; loaded = true; loadedPath = path end
    elseif table.load then
      local ok, data = pcall(table.load, path)
      if ok and type(data) == "table" then DSL_COLOR_DB = data; loaded = true; loadedPath = path end
    end
  end
  DSL_COLOR_DB.version = 14
  DSL_COLOR_DB.people = DSL_COLOR_DB.people or {}
  DSL_COLOR_DB.orgs = DSL_COLOR_DB.orgs or {}
  DSL_COLOR_DB.relations = DSL_COLOR_DB.relations or {}
  DSL_COLOR_DB.relations.people = DSL_COLOR_DB.relations.people or {}
  DSL_COLOR_DB.relations.orgs = DSL_COLOR_DB.relations.orgs or {}
  DSL_COLOR_DB.teams = DSL_COLOR_DB.teams or {}
  DSL_COLOR_DB.titles = DSL_COLOR_DB.titles or {}
  DSL_COLOR_DB.title_blocklist = DSL_COLOR_DB.title_blocklist or {}
  DSL_COLOR_DB.tags = DSL_COLOR_DB.tags or {}
  DSL_COLOR_DB.terms = DSL_COLOR_DB.terms or {}
  DSL_COLOR_DB.custom_palettes = DSL_COLOR_DB.custom_palettes or {}
  DSL_COLOR_DB.overrides = DSL_COLOR_DB.overrides or {}
  DSL_COLOR_DB.ignored = DSL_COLOR_DB.ignored or {}
  DSL_COLOR_DB.aliases = DSL_COLOR_DB.aliases or {}
  DSL_COLOR_DB.settings = DSL_COLOR_DB.settings or {}
  if DSL_COLOR_DB.settings.enabled == nil then DSL_COLOR_DB.settings.enabled = true end
  if DSL_COLOR_DB.settings.echo_updates == nil then DSL_COLOR_DB.settings.echo_updates = true end
  DSL_COLOR_DB.settings.enemy_background = DSL_COLOR_DB.settings.enemy_background or {45, 0, 0}
  if DSL_COLOR_DB.settings.enemy_bold == nil then DSL_COLOR_DB.settings.enemy_bold = true end
  DSL_COLOR_DB.settings.friend_background = DSL_COLOR_DB.settings.friend_background or {0, 35, 25}
  if DSL_COLOR_DB.settings.friend_bold == nil then DSL_COLOR_DB.settings.friend_bold = false end

  -- When the approved default-title seed list changes, clear stale blocks for
  -- current default titles once. After this stamp is current, dslcolor forget
  -- title <default title> still blocks that default normally.
  if DSL_COLOR_DB.default_title_signature ~= DSL_DEFAULT_TITLE_SIGNATURE then
    DSL_COLOR_DB.title_blocklist = DSL_COLOR_DB.title_blocklist or {}
    for title, _ in pairs(DSL_TITLE_ALIASES or {}) do
      DSL_COLOR_DB.title_blocklist[title] = nil
      DSL_COLOR_DB.title_blocklist[string.lower(title)] = nil
    end
    DSL_COLOR_DB.default_title_signature = DSL_DEFAULT_TITLE_SIGNATURE
  end

  -- Pirate reputation normalization: older merged save data may contain
  -- partial reputation fragments as saved titles. Keep the exact reputation
  -- phrases instead: Cabin Person, Pirate, Renown Pirate, Dread Pirate,
  -- Notorious Pirate, Captain. This does not touch people, orgs, palettes,
  -- custom terms, race/class aliases, or combat/census data.
  if DSL_COLOR_DB.pirate_title_signature ~= "release3" then
    DSL_COLOR_DB.titles = DSL_COLOR_DB.titles or {}
    DSL_COLOR_DB.title_blocklist = DSL_COLOR_DB.title_blocklist or {}
    local stalePirateTitleFragments = { "Cabin", "cabin", "Person", "person", "Pirate Captain", "pirate captain" }
    for _, title in ipairs(stalePirateTitleFragments) do
      DSL_COLOR_DB.titles[title] = nil
      DSL_COLOR_DB.title_blocklist[title] = nil
    end
    DSL_COLOR_DB.pirate_title_signature = "release3"
  end

  -- Release cleanup: title_blocklist only applies to current default title aliases.
  -- This removes stale blocks left by older experiments without naming any specific title.
  -- Saved user titles are not touched; use dslcolor forget title <exact title> for those.
  for title, _ in pairs(DSL_COLOR_DB.title_blocklist or {}) do
    if not (DSL_TITLE_ALIASES and DSL_TITLE_ALIASES[title]) then
      DSL_COLOR_DB.title_blocklist[title] = nil
    end
  end

  DSL_COLOR_LAST_LOAD = { ok = loaded, path = loadedPath or DSL_COLOR_DATA_PATH, active_path = DSL_COLOR_DATA_PATH, stamp = os.date("%Y-%m-%d %H:%M:%S") }
end

function dslBlendRgb(a, b, t)
  a = a or {255,255,255}
  b = b or a
  t = t or 0
  return {
    math.floor(a[1] + (b[1] - a[1]) * t),
    math.floor(a[2] + (b[2] - a[2]) * t),
    math.floor(a[3] + (b[3] - a[3]) * t),
  }
end

function dslPaletteColor(palette, idx, len)
  if not palette then return {255, 255, 255} end
  local mode = palette.mode
  if mode == "cycle" or (palette.colors and #palette.colors > 0) then
    local colors = palette.colors or {}
    if #colors == 0 then return {255,255,255} end
    return colors[((idx - 1) % #colors) + 1]
  elseif mode == "gradient" or (palette.from and palette.to) then
    local ratio = 0
    if len and len > 1 then ratio = (idx - 1) / (len - 1) end
    return dslBlendRgb(palette.from, palette.to, ratio)
  elseif mode == "triple" then
    local ratio = 0
    if len and len > 1 then ratio = (idx - 1) / (len - 1) end
    if ratio <= 0.5 then return dslBlendRgb(palette.a, palette.b, ratio / 0.5) end
    return dslBlendRgb(palette.b, palette.c, (ratio - 0.5) / 0.5)
  elseif mode == "mirror" then
    local midpoint = (len + 1) / 2
    local maxDist = midpoint - 1
    local dist = math.abs(idx - midpoint)
    local ratio = 0
    if maxDist > 0 then ratio = dist / maxDist end
    if ratio <= 0.5 then return dslBlendRgb(palette.center, palette.inner, ratio / 0.5) end
    return dslBlendRgb(palette.inner, palette.edge, (ratio - 0.5) / 0.5)
  end
  return palette[1] and palette or {255, 255, 255}
end

DSL_COLOR_LINE_RANGES = DSL_COLOR_LINE_RANGES or {}

function dslResetLineRanges() DSL_COLOR_LINE_RANGES = {} end

function dslRangeIsFree(s, e)
  for _, r in ipairs(DSL_COLOR_LINE_RANGES or {}) do
    if not (e < r[1] or s > r[2]) then return false end
  end
  return true
end

function dslMarkRange(s, e)
  table.insert(DSL_COLOR_LINE_RANGES, {s, e})
end

-- Real perf fix, 2026-08-29, per the maintainer ("I want an optimization pass on
-- this"): dslColorOnLine() calls dslBoundedFind() once per term across
-- the full ~803-term vocabulary (custom terms, names, orgs, titles,
-- craft, race, class), and every single one of those calls used to
-- re-lowercase the SAME real game line from scratch via string.lower(line)
-- -- up to 803 redundant lowercase passes over identical text, once per
-- line of actual game output. Cached here instead: the lowercase form is
-- computed once per real line and reused for every term checked against
-- it, invalidated automatically the moment a genuinely different line
-- comes in (plain string equality, not identity -- cheap relative to the
-- lowercase work it replaces).
local DSL_COLOR_LOWER_CACHE = { line = nil, lower = nil }
local function dslLowerCached(line)
  if DSL_COLOR_LOWER_CACHE.line ~= line then
    DSL_COLOR_LOWER_CACHE.line = line
    DSL_COLOR_LOWER_CACHE.lower = string.lower(line)
  end
  return DSL_COLOR_LOWER_CACHE.lower
end

function dslBoundedFind(line, term, startAt)
  if not line or not term or term == "" then return nil end
  local plainStart = startAt or 1
  local hay = dslLowerCached(line)
  local needle = string.lower(term)
  while true do
    local s, e = hay:find(needle, plainStart, true)
    if not s then return nil end
    local before = s == 1 and "" or line:sub(s-1, s-1)
    local after = e >= #line and "" or line:sub(e+1, e+1)
    if not before:match("[%w_%-']") and not after:match("[%w_%-']") then return s, e end
    plainStart = e + 1
  end
end

function dslColorTextAt(s, e, paletteName)
  local palette = dslGetPalette(paletteName)
  if not palette or not s or not e then return false end
  local len = e - s + 1
  for i=s,e do
    local c = dslPaletteColor(palette, i-s+1, len)
    selectSection(i-1, 1)
    setFgColor(c[1], c[2], c[3])
  end
  resetFormat(); deselect()
  return true
end

function dslColorTermWithPalette(term, paletteName, allowOverlap)
  local line = getCurrentLine()
  local from, changed = 1, false
  while true do
    local s,e = dslBoundedFind(line, term, from)
    if not s then break end
    if allowOverlap or dslRangeIsFree(s, e) then
      changed = dslColorTextAt(s,e,paletteName) or changed
      if not allowOverlap then dslMarkRange(s, e) end
    end
    from = e + 1
  end
  return changed
end

function dslColorTermWithPaletteFrom(term, paletteName, startAt, allowOverlap)
  local line = getCurrentLine()
  local from, changed = startAt or 1, false
  while true do
    local s,e = dslBoundedFind(line, term, from)
    if not s then break end
    if allowOverlap or dslRangeIsFree(s, e) then
      changed = dslColorTextAt(s,e,paletteName) or changed
      if not allowOverlap then dslMarkRange(s, e) end
    end
    from = e + 1
  end
  return changed
end

function dslColorMatch(term, paletteName)
  return dslColorTermWithPalette(term, paletteName)
end

function dslSortedTermKeys(tbl)
  local arr = {}
  for k,_ in pairs(tbl or {}) do if type(k) == "string" and k ~= "" then table.insert(arr, k) end end
  table.sort(arr, function(a,b) return #a > #b end)
  return arr
end

function dslPaletteNameForRace(term)
  local key = (DSL_RACE_ALIASES or {})[term] or (DSL_RACE_ALIASES or {})[string.lower(term or "")]
  return key and (DSL_RACE_KEY_TO_PALETTE or {})[key] or nil
end

function dslIsDragonRaceKey(key)
  if not key then return false end
  key = tostring(key)
  return key:find("_dragon") ~= nil
end

function dslRacePaletteForKey(key)
  if not key then return nil end
  return (DSL_RACE_KEY_TO_PALETTE or {})[key]
end

function dslPersonIdentityPalette(p)
  if not p then return nil end

  -- Normal org identity names use the approved org palette.
  -- Dragon names are special: "( Dragon )" is an identity tag, but the visible
  -- name should use the specific dragon race palette, e.g. brown/gold/crystal/topaz.
  local org = p.clan or p.kingdom or p.robe
  if org and (DSL_ORG_KEY_TO_PALETTE or {})[org] then return DSL_ORG_KEY_TO_PALETTE[org] end

  if p.dragon then
    local dragonRace = p.dragon_type or p.race
    local dragonPalette = dslRacePaletteForKey(dragonRace)
    if dragonPalette then return dragonPalette end
    return (DSL_ORG_KEY_TO_PALETTE or {})[p.dragon]
  end

  return nil
end

function dslPaletteNameForClass(term)
  local key = (DSL_CLASS_ALIASES or {})[term] or (DSL_CLASS_ALIASES or {})[string.lower(term or "")]
  return key and (DSL_CLASS_KEY_TO_PALETTE or {})[key] or nil
end

function dslOrgKeyForTerm(term)
  term = dslStripBrackets(term)
  return (DSL_ORG_ALIASES or {})[term] or (DSL_ORG_ALIASES or {})[string.lower(term)]
end

function dslPaletteNameForOrg(term)
  local key = dslOrgKeyForTerm(term)
  return key and (DSL_ORG_KEY_TO_PALETTE or {})[key] or nil
end

function dslIsTitleBlocked(term)
  if not term or term == "" then return false end
  local block = (DSL_COLOR_DB and DSL_COLOR_DB.title_blocklist) or {}
  local lower = string.lower(term)
  return block[term] == true or block[lower] == true
end

function dslBlockTitle(term)
  term = dslTrim(term or "")
  if term == "" then return false end
  DSL_COLOR_DB.title_blocklist = DSL_COLOR_DB.title_blocklist or {}
  DSL_COLOR_DB.title_blocklist[term] = true
  DSL_COLOR_DB.title_blocklist[string.lower(term)] = true
  return true
end

function dslUnblockTitle(term)
  term = dslTrim(term or "")
  if term == "" then return false end
  DSL_COLOR_DB.title_blocklist = DSL_COLOR_DB.title_blocklist or {}
  DSL_COLOR_DB.title_blocklist[term] = nil
  DSL_COLOR_DB.title_blocklist[string.lower(term)] = nil
  return true
end

function dslTitleCategoryOrPalette(term)
  if not term or term == "" then return nil end
  if dslIsTitleBlocked(term) then return nil end
  local lower = string.lower(term)
  return (DSL_COLOR_DB.titles or {})[term]
      or (DSL_COLOR_DB.titles or {})[lower]
      or (DSL_TITLE_ALIASES or {})[term]
      or (DSL_TITLE_ALIASES or {})[lower]
end

function dslPaletteNameForTitle(term)
  local key = dslTitleCategoryOrPalette(term)
  if not key then return nil end
  return (DSL_TITLE_KEY_TO_PALETTE or {})[key] or key
end

function dslTitleExistsRaw(term)
  term = dslTrim(term or "")
  if term == "" then return false end
  local lower = string.lower(term)
  return ((DSL_COLOR_DB and DSL_COLOR_DB.titles or {})[term] ~= nil)
      or ((DSL_COLOR_DB and DSL_COLOR_DB.titles or {})[lower] ~= nil)
      or ((DSL_TITLE_ALIASES or {})[term] ~= nil)
      or ((DSL_TITLE_ALIASES or {})[lower] ~= nil)
      or ((DSL_COLOR_DB and DSL_COLOR_DB.title_blocklist or {})[term] == true)
      or ((DSL_COLOR_DB and DSL_COLOR_DB.title_blocklist or {})[lower] == true)
end


function dslGetPalette(paletteName)
  if not paletteName or paletteName == "" then return nil end
  if DSL_COLORS and DSL_COLORS.palettes and DSL_COLORS.palettes[paletteName] then return DSL_COLORS.palettes[paletteName] end
  if DSL_COLOR_DB and DSL_COLOR_DB.custom_palettes and DSL_COLOR_DB.custom_palettes[paletteName] then return DSL_COLOR_DB.custom_palettes[paletteName] end
  return nil
end

function dslPaletteExists(paletteName)
  return dslGetPalette(paletteName) ~= nil
end

function dslCustomPaletteNameIsValid(name)
  name = dslTrim(name or "")
  if name == "" then return false end
  if not name:match("^[A-Za-z][A-Za-z0-9_]*$") then return false end
  return true
end

function dslClampRgb(n)
  n = tonumber(n)
  if not n then return nil end
  n = math.floor(n)
  if n < 0 then n = 0 end
  if n > 255 then n = 255 end
  return n
end

function dslPaletteSummary(pal)
  if type(pal) ~= "table" then return "invalid" end
  if pal.mode == "gradient" then
    local a, b = pal.from or {}, pal.to or {}
    return string.format("gradient %s,%s,%s -> %s,%s,%s", tostring(a[1]), tostring(a[2]), tostring(a[3]), tostring(b[1]), tostring(b[2]), tostring(b[3]))
  end
  if pal.mode == "cycle" then
    local parts = {}
    for _, c in ipairs(pal.colors or {}) do table.insert(parts, string.format("%s,%s,%s", tostring(c[1]), tostring(c[2]), tostring(c[3]))) end
    return "cycle " .. table.concat(parts, " | ")
  end
  if pal.mode == "triple" then return "triple" end
  if pal.mode == "mirror" then return "mirror" end
  return tostring(pal.mode or "custom")
end

function dslSaveCustomPalette(name, pal)
  name = dslTrim(name or "")
  if not dslCustomPaletteNameIsValid(name) then cecho("\n<red>[DslColors] bad palette name. Use letters, numbers, and underscores; start with a letter.\n"); return end
  if DSL_COLORS and DSL_COLORS.palettes and DSL_COLORS.palettes[name] then cecho("\n<red>[DslColors] built-in palette names cannot be overwritten: "..name.."\n"); return end
  if type(pal) ~= "table" then cecho("\n<red>[DslColors] invalid palette data.\n"); return end
  DSL_COLOR_DB.custom_palettes = DSL_COLOR_DB.custom_palettes or {}
  DSL_COLOR_DB.custom_palettes[name] = pal
  dslColorSave()
  cecho("\n<green>[DslColors] custom palette saved: "..name.." = "..dslPaletteSummary(pal).."\n")
end

function dslPaletteCommand(cmd)
  local sub = dslTrim(cmd:match("^palette%s+(.+)$") or "")
  if sub == "" then cecho("\n<red>[DslColors] Use: dslcolor palette help\n"); return true end
  if sub == "help" then
    cecho("\n<cyan>Custom palettes\n")
    cecho("<grey>Purpose: create reusable named palettes for dslcolor term and name overrides.\n")
    cecho("<grey>Commands:\n")
    cecho("<grey>  dslcolor palette gradient <name> r1 g1 b1 r2 g2 b2\n")
    cecho("<grey>  dslcolor palette cycle <name> r g b | r g b | r g b\n")
    cecho("<grey>  dslcolor palette copy <new_name> <existing_palette>\n")
    cecho("<grey>  dslcolor palette show <name>\n")
    cecho("<grey>  dslcolor palette remove <name>\n")
    cecho("<grey>  dslcolor list custom_palettes\n")
    cecho("<grey>Example:\n")
    cecho("<grey>  dslcolor palette gradient cliath 180 240 255 255 255 255\n")
    cecho("<grey>  dslcolor term Cliath cliath\n")
    return true
  end
  local name, r1,g1,b1,r2,g2,b2 = sub:match("^gradient%s+(%S+)%s+(%d+)%s+(%d+)%s+(%d+)%s+(%d+)%s+(%d+)%s+(%d+)$")
  if name then
    dslSaveCustomPalette(name, { mode="gradient", from={dslClampRgb(r1),dslClampRgb(g1),dslClampRgb(b1)}, to={dslClampRgb(r2),dslClampRgb(g2),dslClampRgb(b2)} })
    return true
  end
  local copyName, existing = sub:match("^copy%s+(%S+)%s+(%S+)$")
  if copyName and existing then
    local src = dslGetPalette(existing)
    if not src then cecho("\n<red>[DslColors] unknown source palette: "..tostring(existing).."\n"); return true end
    local function clone(v)
      if type(v) ~= "table" then return v end
      local t = {}; for k,val in pairs(v) do t[k] = clone(val) end; return t
    end
    dslSaveCustomPalette(copyName, clone(src))
    return true
  end
  name = sub:match("^remove%s+(%S+)$") or sub:match("^delete%s+(%S+)$")
  if name then
    DSL_COLOR_DB.custom_palettes = DSL_COLOR_DB.custom_palettes or {}
    local existed = DSL_COLOR_DB.custom_palettes[name] ~= nil
    DSL_COLOR_DB.custom_palettes[name] = nil
    dslColorSave()
    if existed then cecho("\n<yellow>[DslColors] custom palette removed: "..name.."\n") else cecho("\n<yellow>[DslColors] no custom palette found: "..name.."\n") end
    return true
  end
  name = sub:match("^show%s+(%S+)$")
  if name then
    local src = "built-in"
    local pal = (DSL_COLORS and DSL_COLORS.palettes and DSL_COLORS.palettes[name])
    if not pal then pal = (DSL_COLOR_DB.custom_palettes or {})[name]; src = "custom" end
    if not pal then cecho("\n<red>[DslColors] unknown palette: "..name.."\n"); return true end
    cecho("\n<cyan>[DslColors] palette "..name.." ("..src.."): "..dslPaletteSummary(pal).."\n")
    return true
  end
  local cycleName, body = sub:match("^cycle%s+(%S+)%s+(.+)$")
  if cycleName and body then
    local colors = {}
    for part in body:gmatch("[^|]+") do
      local r,g,b = part:match("%s*(%d+)%s+(%d+)%s+(%d+)%s*")
      if not r then cecho("\n<red>[DslColors] bad cycle color. Use: r g b | r g b | r g b\n"); return true end
      table.insert(colors, {dslClampRgb(r), dslClampRgb(g), dslClampRgb(b)})
    end
    if #colors == 0 then cecho("\n<red>[DslColors] cycle palette needs at least one color.\n"); return true end
    dslSaveCustomPalette(cycleName, { mode="cycle", colors=colors })
    return true
  end
  cecho("\n<red>[DslColors] unknown palette command. Use: dslcolor palette help\n")
  return true
end

function dslResolvePaletteName(text)
  local t = dslTrim(text or "")
  if t == "" then return nil end
  if dslPaletteExists(t) then return t end
  local lower = string.lower(t)
  if dslPaletteExists(lower) then return lower end

  local friendly = {
    politics = "title_political", political = "title_political",
    royalty = "title_royalty", royal = "title_royalty",
    military = "title_military", religious = "title_religious",
    scholarly = "title_scholarly", craft = "title_craft_titles", crafts = "title_craft_titles",
    unknown = "title_unknown_titles"
  }
  if friendly[lower] and dslPaletteExists(friendly[lower]) then return friendly[lower] end

  local orgKey = dslOrgKeyForTerm(t)
  if orgKey and (DSL_ORG_KEY_TO_PALETTE or {})[orgKey] then return DSL_ORG_KEY_TO_PALETTE[orgKey] end

  local raceKey = (DSL_RACE_ALIASES or {})[t] or (DSL_RACE_ALIASES or {})[lower]
  if raceKey and (DSL_RACE_KEY_TO_PALETTE or {})[raceKey] then return DSL_RACE_KEY_TO_PALETTE[raceKey] end

  local classKey = (DSL_CLASS_ALIASES or {})[t] or (DSL_CLASS_ALIASES or {})[lower]
  if classKey and (DSL_CLASS_KEY_TO_PALETTE or {})[classKey] then return DSL_CLASS_KEY_TO_PALETTE[classKey] end

  local titlePal = dslPaletteNameForTitle(t)
  if titlePal and dslPaletteExists(titlePal) then return titlePal end

  return nil
end

function dslSortedPaletteNames()
  local seen = {}
  local arr = {}
  for k,_ in pairs((DSL_COLORS and DSL_COLORS.palettes) or {}) do if not seen[k] then seen[k]=true; table.insert(arr, k) end end
  for k,_ in pairs((DSL_COLOR_DB and DSL_COLOR_DB.custom_palettes) or {}) do if not seen[k] then seen[k]=true; table.insert(arr, k) end end
  table.sort(arr)
  return arr
end

function dslRenderCustomTerms()
  local changed = false
  local terms = DSL_COLOR_DB and DSL_COLOR_DB.terms or {}
  local sorted = dslSortedTermKeys(terms)
  for _, term in ipairs(sorted) do
    if not dslIsIgnoredTerm(term) then
      local pal = dslResolvePaletteName(terms[term])
      if pal then changed = dslColorTermWithPalette(term, pal) or changed end
    end
  end
  return changed
end

function dslSaveCustomTerm(term, paletteText)
  term = dslTrim(term or "")
  local pal = dslResolvePaletteName(paletteText or "")
  if term == "" then cecho("\n<red>[DslColors] missing term text. Example: dslcolor term \"Verminasian Potions\" verminasia\n"); return end
  if not pal then cecho("\n<red>[DslColors] unknown palette: " .. tostring(paletteText) .. "\n<grey>Use: dslcolor list palettes\n"); return end
  DSL_COLOR_DB.terms = DSL_COLOR_DB.terms or {}
  DSL_COLOR_DB.terms[term] = pal
  dslColorSave()
  cecho("\n<green>[DslColors] custom term saved: " .. term .. " -> " .. pal .. "\n")
end

function dslForgetCustomTerm(term)
  term = dslTrim(term or "")
  if term == "" then cecho("\n<red>[DslColors] missing term to forget.\n"); return end
  DSL_COLOR_DB.terms = DSL_COLOR_DB.terms or {}
  local existed = DSL_COLOR_DB.terms[term] ~= nil
  DSL_COLOR_DB.terms[term] = nil
  dslColorSave()
  if existed then cecho("\n<yellow>[DslColors] custom term forgotten: " .. term .. "\n") else cecho("\n<yellow>[DslColors] no custom term found for: " .. term .. "\n") end
end

function dslParseTermCommand(cmd)
  local term, pal = cmd:match('^term%s+"([^"]+)"%s+([%w_]+)$')
  if term and dslResolvePaletteName(pal) then return term, pal end

  local palFirst, quotedTerm = cmd:match('^term%s+([%w_]+)%s+"([^"]+)"$')
  if palFirst and quotedTerm and dslResolvePaletteName(palFirst) then return quotedTerm, palFirst end

  local body = cmd:match("^term%s+(.+)$")
  if not body then return nil, nil end

  local phrase, last = body:match("^(.+)%s+(%S+)$")
  if phrase and last and dslResolvePaletteName(last) then return phrase, last end

  local first, rest = body:match("^(%S+)%s+(.+)$")
  if first and rest and dslResolvePaletteName(first) then return rest, first end

  return nil, nil
end

function dslAllTitleTermsTable()
  local t = {}
  for k,_ in pairs(DSL_TITLE_ALIASES or {}) do t[k] = true end
  for k,_ in pairs((DSL_COLOR_DB and DSL_COLOR_DB.titles) or {}) do t[k] = true end
  return t
end

function dslColorAnyTermTable(tbl, resolver)
  local changed = false
  for _, term in ipairs(dslSortedTermKeys(tbl or {})) do
    if not dslIsIgnoredTerm(term) then
      local pal = resolver(term)
      if pal then changed = dslColorTermWithPalette(term, pal) or changed end
    end
  end
  return changed
end

function dslColorAllRaceTermsOnLine() return dslColorAnyTermTable(DSL_RACE_ALIASES, dslPaletteNameForRace) end
function dslColorAllClassTermsOnLine() return dslColorAnyTermTable(DSL_CLASS_ALIASES, dslPaletteNameForClass) end
function dslColorAllTitleTermsOnLine(startAt)
  local changed = false
  for _, term in ipairs(dslSortedTermKeys(dslAllTitleTermsTable())) do
    if not dslIsIgnoredTerm(term) then
      local pal = dslPaletteNameForTitle(term)
      if pal then changed = dslColorTermWithPaletteFrom(term, pal, startAt or 1) or changed end
    end
  end
  return changed
end
function dslColorAllCraftTermsOnLine() return dslColorAnyTermTable(DSL_CRAFT_TERMS, function(t) return (DSL_CRAFT_TERMS or {})[t] end) end

function dslOrgTypeForKey(key)
  if not key then return nil end
  local kingdoms = { new_thalos=true, althainia=true, arkane=true, verminasia=true, abaddon=true, nordmaar=true, ganth=true, thaxanos=true, darkonin=true, marauders=true }
  if kingdoms[key] then return "kingdom" end
  if key == "white_robes" or key == "black_robes" or key == "red_robes" then return "robe" end
  if tostring(key):find("dragon") then return "dragon" end
  return "clan"
end

function dslOrgLabelForKey(key)
  local labels = { new_thalos="New Thalos", althainia="Althainia", arkane="Arkane", verminasia="Verminasia", abaddon="Abaddon", nordmaar="Nordmaar", ganth="Ganth", thaxanos="Thaxanos", darkonin="Darkonin", marauders="Marauders", wargar="Wargar", chaos="Chaos", shadow="Shadow", shalonesti_clan="Shalonesti", black_robes="Black Robes", white_robes="White Robes", red_robes="Red Robes", loner="Loner" }
  return labels[key] or tostring(key)
end

function dslEnsurePerson(name)
  local key = dslKey(name)
  if key == "" then return nil end
  local created = false
  if not DSL_COLOR_DB.people[key] then
    DSL_COLOR_DB.people[key] = { name=name, combat={ killed_by_me=0, killed_me=0, downed_by_me=0, downed_me=0, notes={} } }
    created = true
  end
  local p = DSL_COLOR_DB.people[key]
  p.name = p.name or name
  p.combat = p.combat or { killed_by_me=0, killed_me=0, downed_by_me=0, downed_me=0, notes={} }
  p.combat.notes = p.combat.notes or {}
  return key, p, created
end

function dslEnsureOrg(key)
  if not key then return nil end
  DSL_COLOR_DB.orgs[key] = DSL_COLOR_DB.orgs[key] or { key=key, label=dslOrgLabelForKey(key), type=dslOrgTypeForKey(key), palette=(DSL_ORG_KEY_TO_PALETTE or {})[key], members={} }
  local o = DSL_COLOR_DB.orgs[key]
  o.members = o.members or {}
  o.label = o.label or dslOrgLabelForKey(key)
  o.type = o.type or dslOrgTypeForKey(key)
  o.palette = o.palette or (DSL_ORG_KEY_TO_PALETTE or {})[key]
  return o
end

function dslTouchPerson(p, source)
  local now = dslNowRecord()
  if not p.first_seen_real then p.first_seen_real = now.real; p.first_seen_stamp = now.stamp end
  p.last_seen_real = now.real; p.last_seen_stamp = now.stamp; p.last_seen_game_time = now.game_time; p.last_seen_room = now.room; p.last_seen_character = now.character
  p.last_source = source
  p.sightings = (p.sightings or 0) + 1
end


function dslPersonOrgKey(p)
  if not p then return nil end
  return p.clan or p.kingdom or p.robe or p.dragon
end

function dslFactsOrgKey(facts)
  facts = facts or {}
  return facts.clan or facts.kingdom or facts.robe or facts.dragon
end

function dslNameSegmentContains(segment, name)
  local wanted = dslKey(name)
  if wanted == "" then return false end
  for word in tostring(segment or ""):gmatch("[A-Z][%a'%-]*") do
    if dslKey(word) == wanted then return true end
  end
  return false
end

function dslPersonCompatibleWithFacts(p, facts)
  facts = facts or {}
  if not p then return false end
  if facts.class and p.class and facts.class ~= p.class then return false end
  if facts.race and p.race and facts.race ~= p.race then return false end
  local fOrg = dslFactsOrgKey(facts)
  local pOrg = dslPersonOrgKey(p)
  if fOrg and pOrg and fOrg ~= pOrg then return false end
  -- If the incoming line has an org, require the candidate to have that same org.
  -- This keeps surname/secondary-name matching conservative.
  if fOrg and not pOrg then return false end
  return true
end

function dslMergePersonRecords(fromKey, toKey)
  if not fromKey or not toKey or fromKey == toKey then return false end
  local from = DSL_COLOR_DB.people and DSL_COLOR_DB.people[fromKey]
  local to = DSL_COLOR_DB.people and DSL_COLOR_DB.people[toKey]
  if not from or not to then return false end

  for _, field in ipairs({"race","class","kingdom","clan","robe","dragon","dragon_type","title_prefix","team","name_segment","craft","craft_rank","first_seen_real","first_seen_stamp","last_seen_real","last_seen_stamp","last_seen_game_time","last_seen_room","last_seen_character","last_source"}) do
    if to[field] == nil and from[field] ~= nil then to[field] = from[field] end
  end

  to.sightings = (to.sightings or 0) + (from.sightings or 0)

  if from.crafts then
    to.crafts = to.crafts or {}
    for craft, rankInfo in pairs(from.crafts) do
      if to.crafts[craft] == nil then to.crafts[craft] = rankInfo end
    end
  end

  if from.combat then
    to.combat = to.combat or { killed_by_me=0, killed_me=0, downed_by_me=0, downed_me=0, notes={} }
    for _, field in ipairs({"killed_by_me","killed_me","downed_by_me","downed_me"}) do
      to.combat[field] = (to.combat[field] or 0) + (from.combat[field] or 0)
    end
    to.combat.notes = to.combat.notes or {}
    for _, note in ipairs(from.combat.notes or {}) do table.insert(to.combat.notes, note) end
  end

  DSL_COLOR_DB.aliases = DSL_COLOR_DB.aliases or {}
  DSL_COLOR_DB.aliases[fromKey] = toKey

  if DSL_COLOR_DB.relations and DSL_COLOR_DB.relations.people then
    if DSL_COLOR_DB.relations.people[toKey] == nil then DSL_COLOR_DB.relations.people[toKey] = DSL_COLOR_DB.relations.people[fromKey] end
    DSL_COLOR_DB.relations.people[fromKey] = nil
  end

  for _, members in pairs(DSL_COLOR_DB.teams or {}) do
    if members[fromKey] then members[toKey] = true; members[fromKey] = nil end
  end

  for _, org in pairs(DSL_COLOR_DB.orgs or {}) do
    if org.members and org.members[fromKey] then org.members[toKey] = true; org.members[fromKey] = nil end
  end

  DSL_COLOR_DB.people[fromKey] = nil
  return true
end

function dslResolveCanonicalPersonKey(name, facts)
  local key = dslKey(name)
  if key == "" then return key end

  DSL_COLOR_DB.aliases = DSL_COLOR_DB.aliases or {}
  local aliased = DSL_COLOR_DB.aliases[key]
  if aliased and DSL_COLOR_DB.people and DSL_COLOR_DB.people[aliased] then return aliased end

  local candidates = {}
  for pkey, p in pairs(DSL_COLOR_DB.people or {}) do
    if pkey ~= key and p.name_segment and dslNameSegmentContains(p.name_segment, name) and dslPersonCompatibleWithFacts(p, facts) then
      table.insert(candidates, pkey)
    end
  end

  if #candidates == 1 then
    DSL_COLOR_DB.aliases[key] = candidates[1]
    return candidates[1]
  end

  return key
end

function dslLearnPerson(name, facts, source)
  facts = facts or {}
  if dslIsIgnoredTerm(name) then return false end
  local originalKey = dslKey(name)
  local resolvedKey = dslResolveCanonicalPersonKey(name, facts)
  if resolvedKey and resolvedKey ~= originalKey then
    dslMergePersonRecords(originalKey, resolvedKey)
    local resolved = DSL_COLOR_DB.people[resolvedKey]
    if resolved and resolved.name then name = resolved.name end
  end

  local key,p,created = dslEnsurePerson(name); if not p then return false end
  dslTouchPerson(p, source or "structured")

  local changed=created

  -- Crafting can list the same person multiple times, once per craft/profession.
  -- Store crafts as a table so "Miller" does not overwrite "Lumberjack" and then
  -- flip back on the next WHOCRAFT refresh. Echo only when a new craft is learned
  -- or an existing craft's rank/info text actually changes.
  if facts.craft or facts.craft_rank then
    p.crafts = p.crafts or {}
    local craft = facts.craft or "Unknown"
    local rankInfo = facts.craft_rank or craft
    if craft and craft ~= "" then
      if p.crafts[craft] ~= rankInfo then
        p.crafts[craft] = rankInfo
        changed = true
      end

      -- Compatibility/display fields: set once only, do not toggle between crafts.
      p.craft = p.craft or craft
      p.craft_rank = p.craft_rank or rankInfo
    end

    facts.craft = nil
    facts.craft_rank = nil
  end

  -- Preserve the richest title prefix. Short WHOK/WHOC rows may show only one
  -- title/rank, while full WHO rows can show multiple leading titles. Avoid
  -- oscillating between the short and full forms.
  local incomingTitlePrefix = facts.title_prefix
  facts.title_prefix = nil
  if incomingTitlePrefix and incomingTitlePrefix ~= "" then
    local oldPrefix = tostring(p.title_prefix or "")
    if oldPrefix == "" or #incomingTitlePrefix > #oldPrefix then
      p.title_prefix = incomingTitlePrefix
      changed = true
    end
  end

  for k,v in pairs(facts or {}) do
    if v and p[k] ~= v then
      p[k]=v
      changed=true
    end
  end

  local orgKey = p.clan or p.kingdom or p.robe or p.dragon
  if orgKey then
    local o=dslEnsureOrg(orgKey)
    o.members[key]=true
    o.last_seen_real=os.time()
    o.last_seen_stamp=os.date("%Y-%m-%d %H:%M:%S")
  end

  -- Persist every structured sighting. Even when facts are unchanged, last_seen
  -- and sightings changed and must survive a profile reload.
  dslColorSave()

  if changed and DSL_COLOR_DB.settings.echo_updates then
    cecho("\n<cyan>[DslColors] updated "..name.." facts\n")
  end

  return changed
end

function dslIsKnownTitleTerm(term)
  return dslTitleCategoryOrPalette(term) ~= nil
end

function dslLongestLeadingTitle(text)
  text = dslTrim(text or "")
  local lowerText = string.lower(text)
  local best = nil
  local function consider(title)
    if type(title) ~= "string" or title == "" then return end
    if dslIsTitleBlocked(title) then return end
    local esc = string.lower(title):gsub("([^%w%s'])", "%%%1"):gsub("%s+", "%%s+")
    if lowerText:match("^" .. esc .. "%f[%W]") then
      if (not best) or #title > #best then best = title end
    end
  end
  for title,_ in pairs(DSL_TITLE_ALIASES or {}) do consider(title) end
  for title,_ in pairs((DSL_COLOR_DB and DSL_COLOR_DB.titles) or {}) do consider(title) end
  return best
end

function dslStripLeadingStatusAndTitles(text)
  text = dslTrim(text or "")
  local removed = {}

  local guard = 0
  while guard < 10 do
    guard = guard + 1
    local before = text
    local tag = text:match("^%s*%(([^%)]+)%)") or text:match("^%s*%[([^%]]+)%]")
    if tag then
      local clean = dslStripBrackets(tag)
      if DSL_STATUS_ONLY_TAGS[clean] or dslIsKnownTitleTerm(clean) then
        table.insert(removed, clean)
        text = text:gsub("^%s*%b()", "", 1):gsub("^%s*%b[]", "", 1)
        text = dslTrim(text)
      end
    end
    if before == text then break end
  end

  guard = 0
  while guard < 10 do
    guard = guard + 1
    local title = dslLongestLeadingTitle(text)
    if not title then break end
    -- Remove the leading matched title from the original string. Matching is
    -- case-insensitive and whitespace-tolerant, so compute the matched end
    -- position against the lowercased source instead of using a literal gsub.
    local esc = string.lower(title):gsub("([^%w%s'])", "%%%1"):gsub("%s+", "%%s+")
    local _, titleEnd = string.lower(text):find("^" .. esc)
    local displayedTitle = title
    if titleEnd then displayedTitle = dslTrim(text:sub(1, titleEnd)) end
    table.insert(removed, displayedTitle)
    if titleEnd then text = dslTrim(text:sub(titleEnd + 1)) else text = dslTrim(text:sub(#title + 1)) end
  end

  return text, removed
end


function dslLeadingNameSegment(text)
  local s = dslTrim(text or "")
  local words = {}
  local pos = 1

  while pos <= #s do
    local spaceStart, spaceEnd = s:find("^%s+", pos)
    if spaceStart then pos = spaceEnd + 1 end

    local a, b, word = s:find("^([A-Z][%a'%-]*)", pos)
    if not word then break end

    table.insert(words, word)
    pos = b + 1

    local nextChar = s:sub(pos, pos)
    if nextChar ~= " " then break end
  end

  return table.concat(words, " ")
end

function dslExtractName(text)
  local clean = dslStripLeadingStatusAndTitles(text or "")
  local segment = dslLeadingNameSegment(clean)
  return segment:match("^([A-Z][%a'%-]+)")
end

function dslProcessStructuredText(line, source)
  line = line or getCurrentLine()

  local level, race, class, rest = line:match("^%s*#?%d*%.?%s*%[%s*(%d+)%s+([%w%-]+)%s+([%a]+)%s*%]%s*(.*)$")
  local hasRace = true

  if not rest then
    level, class, rest = line:match("^%s*#?%d*%.?%s*%[%s*(%d+)%s+([%a]+)%s*%]%s*(.*)$")
    hasRace = false
  end

  if not rest then return false end

  -- Master Account character-list rows start with "#1.". They should color like
  -- structured rows, but must not learn/update people or aliases from your own alt list.
  local masterListRow = line:match("^%s*#%d+%.") ~= nil

  local facts = {}
  if hasRace and race then facts.race = (DSL_RACE_ALIASES or {})[race] or (DSL_RACE_ALIASES or {})[string.lower(race or "")] or race end
  if class then facts.class = (DSL_CLASS_ALIASES or {})[class] or (DSL_CLASS_ALIASES or {})[string.lower(class or "")] or class end

  -- Dragon rows look like: [51 Brown Dra] ( Dragon ) Ryzzynth
  -- The "Dragon" tag is the broad identity/org for relation purposes, but the
  -- name color should be the specific dragon race palette from the race column.
  if facts.class == "dragon" or dslIsDragonRaceKey(facts.race) then
    facts.dragon = "dragon"
    facts.dragon_type = facts.race
  end

  local scan = rest
  local guard = 0
  while guard < 8 do
    guard = guard + 1
    local tag = scan:match("^%s*%(([^%)]+)%)") or scan:match("^%s*%[([^%]]+)%]")
    if not tag then break end
    local clean = dslStripBrackets(tag)
    if not DSL_STATUS_ONLY_TAGS[clean] then
      local orgKey = dslOrgKeyForTerm(clean)
      if orgKey then
        local typ = dslOrgTypeForKey(orgKey)
        if typ == "kingdom" then facts.kingdom = orgKey elseif typ == "robe" then facts.robe = orgKey elseif typ == "dragon" then facts.dragon = "dragon"; facts.dragon_type = facts.dragon_type or facts.race else facts.clan = orgKey end
      end
    end
    scan = scan:gsub("^%s*%b()", "", 1):gsub("^%s*%b[]", "", 1)
  end

  local nameScan, strippedTitles = dslStripLeadingStatusAndTitles(scan)
  local nameSegment = dslLeadingNameSegment(nameScan)
  local name = dslExtractName(scan)

  if name and not masterListRow then
    -- Only full WHO-style rows with race+class are allowed to refresh the rich
    -- name segment. WHOK/WHOC class-only rows often contain short names plus
    -- rank columns, and letting those overwrite the full segment caused
    -- repeated update echoes when moving between who/whok/whoc.
    if hasRace and nameSegment and nameSegment ~= "" then facts.name_segment = nameSegment end
    if strippedTitles and #strippedTitles > 0 then facts.title_prefix = table.concat(strippedTitles, ", ") end
    local paletteKey = facts.kingdom or facts.clan or facts.robe or facts.dragon
    if paletteKey then DSL_COLOR_DB.overrides[name] = nil end
    local effectiveSource = source or (hasRace and "who" or "who-short")
    if source == "who" and not hasRace then effectiveSource = "who-short" end
    dslLearnPerson(name, facts, effectiveSource)
  end

  return true
end

function dslColorProcessStructuredLine() return dslProcessStructuredText(getCurrentLine(), "who") end

DSL_CRAFT_PROFESSIONS = {
  "Armorcrafter", "Spellcrafter", "Weaponsmith", "Lumberjack", "Smelter",
  "Tanner", "Tailor", "Hunter", "Miller", "Miner"
}

function dslExtractCraftInfo(info)
  info = dslTrim(info or "")
  local profession = nil
  for _, term in ipairs(DSL_CRAFT_PROFESSIONS) do
    if info:find(term, 1, true) then profession = term; break end
  end
  if not profession then return nil, nil end

  local rank = dslTrim(info:match("^(.-)%s+" .. profession) or "")
  if rank == "" then rank = "Unknown" end

  local subtype = info:match(profession .. "%s*%((Sharp)%)") or info:match(profession .. "%s*%((Blunt)%)")
  local craftKey = profession
  if subtype then craftKey = profession .. " (" .. subtype .. ")" end

  local rankInfo = rank .. " " .. craftKey
  return craftKey, rankInfo
end

function dslOrgFactsFromText(text)
  local facts = {}
  for tag in text:gmatch("%b[]") do
    local clean = dslStripBrackets(tag)
    if not DSL_STATUS_ONLY_TAGS[clean] then
      local orgKey = dslOrgKeyForTerm(clean)
      if orgKey then
        local typ = dslOrgTypeForKey(orgKey)
        if typ == "kingdom" then facts.kingdom = orgKey elseif typ == "robe" then facts.robe = orgKey elseif typ == "dragon" then facts.dragon = "dragon" else facts.clan = orgKey end
      end
    end
  end
  for tag in text:gmatch("%b()") do
    local clean = dslStripBrackets(tag)
    if not DSL_STATUS_ONLY_TAGS[clean] and clean ~= "Sharp" and clean ~= "Blunt" then
      local orgKey = dslOrgKeyForTerm(clean)
      if orgKey then
        local typ = dslOrgTypeForKey(orgKey)
        if typ == "kingdom" then facts.kingdom = orgKey elseif typ == "robe" then facts.robe = orgKey elseif typ == "dragon" then facts.dragon = "dragon" else facts.clan = orgKey end
      end
    end
  end
  return facts
end

function dslProcessCraftLine(line)
  line = line or getCurrentLine()
  local name, info = line:match("^%s*([A-Z][%a'%-]+)%s+%-%s+(.+)$")
  if not name or not info then return false end

  local craft, rankInfo = dslExtractCraftInfo(info)
  if not craft then return false end

  local facts = dslOrgFactsFromText(info)
  facts.craft = craft
  facts.craft_rank = rankInfo

  -- If a craft line ends with a known leading title after the org, preserve it as metadata
  -- but never let it become the learned name because the name is already before the dash.
  local stripped = info
  stripped = stripped:gsub("%b[]", " "):gsub("%b()", " ")
  local _, titles = dslStripLeadingStatusAndTitles(stripped)
  if titles and #titles > 0 then facts.title_prefix = table.concat(titles, ", ") end

  dslLearnPerson(name, facts, "whocraft")
  return true
end

function dslRelationForPerson(pkey, p)
  local rel = DSL_COLOR_DB.relations.people[pkey]
  if rel then return rel end
  local org = p and (p.clan or p.kingdom or p.robe or p.dragon)
  if org then return DSL_COLOR_DB.relations.orgs[org] end
  return nil
end

function dslApplyRelationBackground(name, relation)
  if not name or not relation or relation == "neutral" then return false end
  local bg, bold
  if relation == "enemy" or relation == "war" then bg = DSL_COLOR_DB.settings.enemy_background; bold = DSL_COLOR_DB.settings.enemy_bold
  elseif relation == "friend" or relation == "peace" then bg = DSL_COLOR_DB.settings.friend_background; bold = DSL_COLOR_DB.settings.friend_bold end
  if not bg then return false end
  local line=getCurrentLine(); local from=1; local changed=false
  while true do
    local s,e=dslBoundedFind(line, name, from); if not s then break end
    for i=s,e do selectSection(i-1,1); setBgColor(bg[1],bg[2],bg[3]); if bold then pcall(setBold,true) end end
    resetFormat(); deselect(); changed=true; from=e+1
  end
  return changed
end

function dslRenderNameOverrides()
  local changed=false
  for name,pal in pairs(DSL_COLOR_DB.overrides or {}) do
    if not dslIsIgnoredTerm(name) then changed=dslColorTermWithPalette(name,pal) or changed end
  end
  return changed
end

function dslRenderKnownNames()
  local changed=false
  for key,p in pairs(DSL_COLOR_DB.people or {}) do
    local name=p.name
    if name and not dslIsIgnoredTerm(name) then
      local isTitleName = dslIsKnownTitleTerm(name)
      if not isTitleName and not (DSL_COLOR_DB.overrides and DSL_COLOR_DB.overrides[name]) then
        local pal=dslPersonIdentityPalette(p)
        if pal then changed=dslColorTermWithPalette(name,pal) or changed end
      end
      local rel=dslRelationForPerson(key,p)
      if rel then changed=dslApplyRelationBackground(name,rel) or changed end
    end
  end
  return changed
end

function dslRenderOrgTags()
  local line=getCurrentLine(); local changed=false
  for tag in line:gmatch("%[([^%]]+)%]") do local clean=dslStripBrackets(tag); if not DSL_STATUS_ONLY_TAGS[clean] then local pal=dslPaletteNameForOrg(clean); if pal then changed=dslColorTermWithPalette(clean,pal) or changed end end end
  for tag in line:gmatch("%(([^%)]+)%)") do local clean=dslStripBrackets(tag); if not DSL_STATUS_ONLY_TAGS[clean] then local pal=dslPaletteNameForOrg(clean); if pal then changed=dslColorTermWithPalette(clean,pal) or changed end end end
  return changed
end

function dslColorOnLine()
  -- Real gap fix, 2026-08-29, per the maintainer ("dslcolor needs to be
  -- integrated into MyDSL, it will toggle on off like the others" +
  -- "fix the known issues"): no master on/off ever existed -- only
  -- echo_updates (notification verbosity, not the scan itself). The
  -- full ~803-term vocabulary scan ran unconditionally on every
  -- non-blank line regardless. "dslcolor on|off" now controls this.
  if not (DSL_COLOR_DB and DSL_COLOR_DB.settings and DSL_COLOR_DB.settings.enabled) then return end
  local line = getCurrentLine()
  if not line or line == "" then return end
  dslResetLineRanges()

  local structured = dslProcessStructuredText(line, "who")
  local craftline = dslProcessCraftLine(line)

  -- Rendering priority: custom terms, manual name overrides, known people,
  -- org tags, titles/craft terms, then race/class vocabulary.
  dslRenderCustomTerms()
  dslRenderNameOverrides()
  dslRenderKnownNames()
  dslRenderOrgTags()

  -- Title/craft terms are useful on WHO/WHOCRAFT-style people lines, but noisy
  -- on login menus such as "Master Account". Keep them scoped to structured lines.
  if structured or craftline then
    local titleStart = 1
    if structured then
      local _, structuredHeaderEnd = line:find("^%s*#?%d*%.?%s*%b[]")
      if structuredHeaderEnd then titleStart = structuredHeaderEnd + 1 end
    end
    dslColorAllTitleTermsOnLine(titleStart)
    dslColorAllCraftTermsOnLine()
  end

  dslColorAllRaceTermsOnLine()
  dslColorAllClassTermsOnLine()
end

function dslCount(t) local n=0; for _,_ in pairs(t or {}) do n=n+1 end; return n end
function dslPrintKV(k,v) cecho("<grey>  "..k..": <cyan>"..tostring(v or "-").."\n") end

function dslResolveOrgKey(text)
  local k=dslOrgKeyForTerm(text); if k then return k end
  return dslKey(text)
end

function dslSetPersonRelation(name, rel)
  local key,p=dslEnsurePerson(name)
  if rel=="neutral" then DSL_COLOR_DB.relations.people[key]=nil; cecho("\n<yellow>[DslColors] personal relation cleared: "..p.name.."\n")
  else DSL_COLOR_DB.relations.people[key]=rel; cecho("\n<green>[DslColors] personal relation: "..p.name.." -> "..rel.."\n") end
  dslColorSave()
end

function dslSetOrgRelation(orgText, rel)
  local key=dslResolveOrgKey(orgText); local o=dslEnsureOrg(key)
  if rel=="neutral" then DSL_COLOR_DB.relations.orgs[key]=nil; cecho("\n<yellow>[DslColors] org relation cleared: "..o.label.."\n")
  else DSL_COLOR_DB.relations.orgs[key]=rel; cecho("\n<green>[DslColors] org relation: "..o.label.." -> "..rel.."\n") end
  dslColorSave()
end

function dslShowPerson(name)
  local p=DSL_COLOR_DB.people[dslKey(name)]
  if not p then cecho("\n<yellow>[DslColors] No person record for "..tostring(name).."\n"); return end
  cecho("\n<cyan>DSL person: "..tostring(p.name).."\n")
  for _,k in ipairs({"race","class","kingdom","clan","robe","dragon","dragon_type","title_prefix","name_segment","team","first_seen_stamp","last_seen_stamp","last_seen_game_time","last_seen_room","sightings"}) do dslPrintKV(k,p[k]) end

  if p.crafts and next(p.crafts) then
    cecho("<grey>  crafts:\n")
    local keys={}
    for craft,_ in pairs(p.crafts) do table.insert(keys, craft) end
    table.sort(keys)
    for _,craft in ipairs(keys) do
      cecho("<grey>    "..tostring(craft)..": <cyan>"..tostring(p.crafts[craft]).."\n")
    end
  else
    dslPrintKV("craft", p.craft)
    dslPrintKV("craft_rank", p.craft_rank)
  end

  if p.combat then dslPrintKV("killed_by_me",p.combat.killed_by_me); dslPrintKV("killed_me",p.combat.killed_me); dslPrintKV("downed_by_me",p.combat.downed_by_me); dslPrintKV("downed_me",p.combat.downed_me) end
end

function dslShowOrg(text)
  local key=dslResolveOrgKey(text); local o=DSL_COLOR_DB.orgs[key]
  if not o then cecho("\n<yellow>[DslColors] No org record for "..tostring(text).."\n"); return end
  cecho("\n<cyan>DSL org: "..o.label.."\n"); dslPrintKV("key",key); dslPrintKV("type",o.type); dslPrintKV("relation",DSL_COLOR_DB.relations.orgs[key] or "neutral"); dslPrintKV("known_members",dslCount(o.members)); dslPrintKV("last_seen",o.last_seen_stamp)
end

function dslCensus(field)
  field=dslTrim(field or "")
  if field=="" then cecho("\n<cyan>DSL census summary\n"); dslPrintKV("known_people",dslCount(DSL_COLOR_DB.people)); dslPrintKV("known_orgs",dslCount(DSL_COLOR_DB.orgs)); return end
  if field=="lastseen" then local arr={}; for _,p in pairs(DSL_COLOR_DB.people) do table.insert(arr,p) end; table.sort(arr,function(a,b)return (a.last_seen_real or 0)>(b.last_seen_real or 0)end); cecho("\n<cyan>Recently seen\n"); for i=1,math.min(20,#arr) do local p=arr[i]; cecho("<grey>  "..tostring(p.name).." <cyan>"..tostring(p.last_seen_stamp or "-").."<grey> room="..tostring(p.last_seen_room or "-").."\n") end; return end
  if field=="combat" then cecho("\n<cyan>Combat census\n"); for _,p in pairs(DSL_COLOR_DB.people) do local c=p.combat or {}; local total=(c.killed_by_me or 0)+(c.killed_me or 0)+(c.downed_by_me or 0)+(c.downed_me or 0); if total>0 then cecho("<grey>  "..p.name..": killed_by_me="..(c.killed_by_me or 0).." killed_me="..(c.killed_me or 0).." downed_by_me="..(c.downed_by_me or 0).." downed_me="..(c.downed_me or 0).."\n") end end; return end

  local counts={}
  for _,p in pairs(DSL_COLOR_DB.people) do
    if field=="craft" then
      if p.crafts and next(p.crafts) then
        for craft,_ in pairs(p.crafts) do counts[craft]=(counts[craft] or 0)+1 end
      elseif p.craft then
        counts[p.craft]=(counts[p.craft] or 0)+1
      end
    else
      local v=p[field]
      if field=="relation" then v=DSL_COLOR_DB.relations.people[dslKey(p.name or "")] end
      if v then counts[v]=(counts[v] or 0)+1 end
    end
  end

  cecho("\n<cyan>DSL census: "..field.."\n")
  for k,v in pairs(counts) do cecho("<grey>  "..tostring(k)..": <cyan>"..tostring(v).."\n") end
end

function dslCombatEvent(name, field, note)
  local key,p=dslEnsurePerson(name); local c=p.combat; c[field]=(c[field] or 0)+1; local now=dslNowRecord(); c.last_combat_stamp=now.stamp; table.insert(c.notes,{stamp=now.stamp, room=now.room, game_time=now.game_time, type=field, note=note}); dslColorSave(); cecho("\n<green>[DslColors] combat recorded: "..p.name.." "..field.." = "..c[field].."\n")
end

function dslColorHelp(topic)
  topic = string.lower(dslTrim(topic or ""))

  local H = "<cyan>"      -- main header: cyan-teal
  local S = "<yellow>"      -- section title: warm gold
  local B = "<grey>"     -- body text: soft gray, not bright white
  local D = "<grey>"     -- dim explanatory text
  local C = "<green>"     -- commands/examples: soft green
  local W = "<yellow>"      -- warnings/notes: amber
  local R = "<red>"     -- errors/cautions: soft red

  local function header(text) cecho("\n" .. H .. "== " .. text .. " ==\n") end
  local function section(text) cecho(S .. "\n" .. text .. "\n") end
  local function body(text) cecho(B .. text .. "\n") end
  local function dim(text) cecho(D .. text .. "\n") end
  local function cmd(text, desc)
    if desc and desc ~= "" then cecho(C .. "  " .. text .. D .. "  - " .. desc .. "\n") else cecho(C .. "  " .. text .. "\n") end
  end
  local function note(text) cecho(W .. text .. "\n") end

  if topic == "" or topic == "overview" or topic == "main" then
    header("DslColors v1.0")
    body("Persistent identity coloring and conservative people tracking for Dark and Shattered Lands.")
    body("It colors visible text in Mudlet. It does not rewrite game output or send game commands.")
    body("Save file: " .. tostring(DSL_COLOR_DATA_PATH or "DSL_PeopleColors_data.lua"))
    section("Core idea")
    body("Foreground color shows factual identity: race, class, kingdom, clan, robe, dragon type, title, craft, custom term, or learned person palette.")
    body("Relationship overlays can add background/bold for friend, enemy, peace, or war without replacing the foreground identity color.")
    section("Help topics")
    cmd("dslcolor help commands", "all command groups")
    cmd("dslcolor help quickstart", "safe first steps after install")
    cmd("dslcolor help parsing", "how WHO / WHOK / WHOC / WHOCRAFT learning works")
    cmd("dslcolor help titles", "fix title/name capture issues")
    cmd("dslcolor help terms", "custom exact word/phrase coloring")
    cmd("dslcolor help palettes", "built-in and custom palette commands")
    cmd("dslcolor help relationships", "friend/enemy/peace/war overlays")
    cmd("dslcolor help census", "stored fact summaries")
    cmd("dslcolor help combat", "manual combat history notes")
    cmd("dslcolor help teams", "private team labels")
    cmd("dslcolor help maintenance", "save, reload, ignore, forget, cleanup")
    cmd("dslcolor help examples", "common workflows")
    return
  end

  if topic == "quickstart" or topic == "install" then
    header("Quickstart")
    body("After importing or updating the package, reload the Mudlet profile once, then run:")
    cmd("dslcolor test", "confirms the core script, alias, counts, and save status")
    cmd("dslcolor savepath", "shows the exact persistent save file")
    cmd("dslcolor list titles", "shows default and saved leading titles")
    cmd("who", "lets DslColors learn full WHO rows")
    cmd("whok", "adds kingdom facts without downgrading richer WHO name data")
    cmd("whoc", "adds clan/robe/order facts without downgrading richer WHO name data")
    cmd("who", "a second WHO should usually be quiet unless real facts changed")
    note("If a rank/title is captured as a name, add it as an exact title, clean it, then WHO again.")
    return
  end

  if topic == "commands" then
    header("Command list")
    section("Inspect")
    cmd("dslcolor test", "runtime check: paths, counts, load/save status")
    cmd("dslcolor savepath", "print the save-file path")
    cmd("dslcolor show person <name>", "show stored person facts")
    cmd("dslcolor show <name>", "shorthand for show person")
    cmd("dslcolor show org <org>", "show stored organization facts")
    cmd("dslcolor list people|orgs|friends|enemies|war|peace|teams|titles|terms|palettes|custom_palettes", "list stored data")
    section("Relationships")
    cmd("dslcolor friend <name>", "personal friendly overlay")
    cmd("dslcolor enemy <name>", "personal enemy overlay")
    cmd("dslcolor neutral <name>", "clear personal relation")
    cmd("dslcolor peace <org>", "organization peace overlay")
    cmd("dslcolor war <org>", "organization war overlay")
    cmd("dslcolor neutral org <org>", "clear organization relation")
    section("Titles")
    cmd("dslcolor title royalty|military|political|religious|scholarly|craft|unknown <exact title>", "add an exact leading title")
    cmd("dslcolor forget title <exact title>", "remove a saved title or block a default title")
    cmd("dslcolor cleanup-title", "remove accidental person records whose name is now an active title")
    section("Custom terms and palettes")
    cmd("dslcolor term <phrase> <palette>", "color an exact word/phrase")
    cmd("dslcolor term <palette> <phrase>", "same command with palette first")
    cmd("dslcolor forget term <phrase>", "remove a custom term")
    cmd("dslcolor palette help", "custom palette syntax")
    section("Census and combat")
    cmd("dslcolor census race|class|kingdom|clan|robe|dragon|craft|relation|lastseen|combat", "summarize saved facts")
    cmd("dslcolor killed <name> / killedby <name>", "manual combat history")
    cmd("dslcolor downed <name> / downedby <name>", "manual down/disable history")
    cmd("dslcolor combat note <name> <note>", "timestamped combat note")
    section("Maintenance")
    cmd("dslcolor on|off", "master toggle -- turns the whole scan off, not just echoes")
    cmd("dslcolor echo on|off", "show/hide update echoes")
    cmd("dslcolor save", "manual save")
    cmd("dslcolor reload", "reload from disk")
    cmd("dslcolor ignore <name/term>", "stop learning/coloring a problematic token as a person")
    cmd("dslcolor unignore <name/term>", "reverse ignore")
    cmd("dslcolor forget person <name>", "delete a bad person record and related aliases")
    cmd("dslcolor forget name <name>", "remove a manual name palette override")
    return
  end

  if topic == "parsing" or topic == "flow" then
    header("Parsing flow")
    body("DslColors learns people only from structured lines it recognizes, mainly WHO-style output.")
    body("Full WHO rows are the richest source and may update race, class, org, title-prefix, name segment, and last-seen data.")
    body("WHOK, WHOC, and WHOCRAFT may add compatible facts, but should not replace richer full-WHO name data with shorter fragments.")
    body("Login banners and menu text are not intended as learning sources.")
    section("Name extraction")
    body("1. Detect a structured WHO-like row.")
    body("2. Strip status markers such as WANTED or AFK.")
    body("3. Read race/class/org fields when present.")
    body("4. Strip only active exact leading titles.")
    body("5. Capture the first remaining real name token as the person key.")
    note("Phrase titles remain phrases. Adding 'Dread Pirate' does not create 'Dread' or 'Pirate'.")
    return
  end

  if topic == "relationships" then
    header("Relationships")
    body("Relationship commands add visual overlays. They do not change the factual foreground identity color.")
    section("People")
    cmd("dslcolor friend <name>", "mark one person as friendly")
    cmd("dslcolor enemy <name>", "mark one person as enemy")
    cmd("dslcolor neutral <name>", "clear personal relation")
    section("Organizations")
    cmd("dslcolor peace <org>", "friendly/peace overlay for known members")
    cmd("dslcolor war <org>", "enemy/war overlay for known members")
    cmd("dslcolor neutral org <org>", "clear org relation")
    note("Personal relation wins over organization relation when both apply.")
    return
  end

  if topic == "titles" then
    header("Titles and name capture")
    body("A title is an exact leading word or phrase that should be skipped before learning a person's name.")
    body("Default title seeds are intentionally small. Add new titles through commands when logs prove them.")
    section("Commands")
    cmd("dslcolor title royalty <title>", "royal/noble title such as King or Sultan")
    cmd("dslcolor title military <title>", "rank or military title such as Knight or Dread Pirate")
    cmd("dslcolor title religious <title>", "faith/religious title such as Deacon")
    cmd("dslcolor title scholarly <title>", "mage/scholar title")
    cmd("dslcolor title craft <title>", "craft/profession title")
    cmd("dslcolor title unknown <title>", "uncategorized exact title")
    cmd("dslcolor forget title <title>", "remove saved title or block default title")
    cmd("dslcolor cleanup-title", "delete bad person records that are active titles")
    cmd("dslcolor list titles", "show active titles and whether each is default or saved")
    section("Safe workflow")
    body("If 'Sultan Meki' learned as person 'Sultan':")
    cmd("dslcolor title royalty Sultan", "teach the exact title")
    cmd("dslcolor cleanup-title", "remove title-as-person records")
    cmd("who", "relearn the correct person")
    note("Do not add class words as titles unless the exact game output requires it. Pirate is a class term unless deliberately added as a title phrase.")
    return
  end

  if topic == "terms" then
    header("Custom terms")
    body("Custom terms persistently color exact words or phrases. They are visual-only and do not affect people learning.")
    section("Commands")
    cmd("dslcolor term <phrase> <palette>", "save a custom term")
    cmd("dslcolor term <palette> <phrase>", "same command, palette first")
    cmd("dslcolor term \"multi word phrase\" <palette>", "quoted phrase form")
    cmd("dslcolor forget term <phrase>", "remove a custom term")
    cmd("dslcolor list terms", "show saved custom terms")
    cmd("dslcolor list palettes", "show built-in and custom palette keys")
    section("Examples")
    cmd("dslcolor term \"Verminasian Potions\" verminasia", "color a shop/phrase")
    cmd("dslcolor palette gradient cliath 180 240 255 255 255 255", "create a custom palette")
    cmd("dslcolor term Cliath cliath", "use the custom palette on a term")
    return
  end

  if topic == "palettes" or topic == "palette" or topic == "colors" then
    header("Palettes")
    body("Palettes are reusable color definitions. Built-in palettes color races, classes, orgs, titles, and relation overlays.")
    body("Custom palettes are saved by name and can be used by custom terms and manual name overrides.")
    section("Inspect")
    cmd("dslcolor list palettes", "show built-in and custom palette names")
    cmd("dslcolor list custom_palettes", "show only user-created palettes")
    cmd("dslcolor palette show <name>", "show a custom palette definition")
    section("Create")
    cmd("dslcolor palette gradient <name> r1 g1 b1 r2 g2 b2", "two-color gradient")
    cmd("dslcolor palette cycle <name> r g b | r g b | r g b", "cycle through several colors")
    cmd("dslcolor palette copy <new_name> <existing_palette>", "clone a built-in or custom palette")
    cmd("dslcolor palette remove <name>", "remove a custom palette")
    section("Examples")
    cmd("dslcolor palette gradient cliath 180 240 255 255 255 255", "soft icy gradient")
    cmd("dslcolor palette cycle warning 255 170 60 | 255 90 40 | 220 220 90", "three-color cycle")
    cmd("dslcolor palette copy my_nt new_thalos", "start from an existing palette")
    note("Custom palette names should not collide with built-in palette names.")
    return
  end

  if topic == "census" then
    header("Census")
    body("Census commands summarize the current saved database. They do not query the game by themselves.")
    cmd("dslcolor census race", "count known people by race")
    cmd("dslcolor census class", "count known people by class")
    cmd("dslcolor census kingdom", "count known people by kingdom")
    cmd("dslcolor census clan", "count known people by clan/organization")
    cmd("dslcolor census robe", "count robe/order style data")
    cmd("dslcolor census dragon", "count dragon grouping data")
    cmd("dslcolor census craft", "count craft facts")
    cmd("dslcolor census relation", "count friend/enemy/peace/war data")
    cmd("dslcolor census lastseen", "show recent sightings")
    cmd("dslcolor census combat", "summarize stored combat notes")
    return
  end

  if topic == "combat" then
    header("Combat history")
    body("Combat tracking is manual unless exact DSL kill/death text is later confirmed and approved.")
    cmd("dslcolor killed <name>", "you killed them")
    cmd("dslcolor killedby <name>", "they killed you")
    cmd("dslcolor downed <name>", "you downed/disabled them")
    cmd("dslcolor downedby <name>", "they downed/disabled you")
    cmd("dslcolor combat note <name> <note>", "add a timestamped note")
    cmd("dslcolor combat show <name>", "show person record with combat data")
    return
  end

  if topic == "teams" then
    header("Teams")
    body("Teams are private labels for your own organization. They are not canon identity and do not change colors by themselves.")
    cmd("dslcolor team <name> <label>", "place a person into a private team")
    cmd("dslcolor team <name> none", "remove a person from their team")
    cmd("dslcolor list teams", "show private teams")
    return
  end

  if topic == "maintenance" then
    header("Maintenance")
    cmd("dslcolor on|off", "master toggle -- turns the whole scan off, not just echoes")
    cmd("dslcolor echo on|off", "toggle update echoes")
    cmd("dslcolor save", "save database")
    cmd("dslcolor savepath", "show save file path")
    cmd("dslcolor reload", "reload database from disk")
    cmd("dslcolor ignore <name/term>", "stop learning/coloring a problematic person token")
    cmd("dslcolor unignore <name/term>", "reverse ignore")
    cmd("dslcolor forget person <name>", "remove a bad learned person record")
    cmd("dslcolor forget name <name>", "remove a manual name-palette override")
    cmd("dslcolor forget title <title>", "remove/block an exact title")
    cmd("dslcolor forget term <phrase>", "remove a custom term")
    cmd("dslcolor cleanup-title", "remove title-as-person records")
    return
  end

  if topic == "examples" then
    header("Examples")
    section("Fix a title captured as a name")
    cmd("dslcolor title royalty Sultan", "teach the title")
    cmd("dslcolor cleanup-title", "remove bad title-as-person records")
    cmd("who", "relearn correct names")
    section("Add a phrase title")
    cmd("dslcolor title military \"Dread Pirate\"", "one exact phrase title")
    note("This does not add Dread alone or Pirate alone.")
    section("Custom palette and term")
    cmd("dslcolor palette gradient cliath 180 240 255 255 255 255", "create palette")
    cmd("dslcolor term Cliath cliath", "color term with it")
    section("Relations")
    cmd("dslcolor war Wargar", "mark organization as hostile")
    cmd("dslcolor peace New Thalos", "mark organization as peaceful")
    cmd("dslcolor enemy Ryger", "personal override")
    section("Saved facts")
    cmd("dslcolor show person Ryger", "inspect person")
    cmd("dslcolor census lastseen", "review recent sightings")
    return
  end

  cecho("\n" .. R .. "[DslColors] Unknown help topic. Use: dslcolor help\n")
end

function dslList(what)
  what=dslTrim(what or "")
  cecho("\n<cyan>DslColors list: "..what.."\n")
  if what=="people" then for _,p in pairs(DSL_COLOR_DB.people or {}) do cecho("<grey>  "..tostring(p.name).." last="..tostring(p.last_seen_stamp or "-").."\n") end; return end
  if what=="orgs" then for k,o in pairs(DSL_COLOR_DB.orgs or {}) do cecho("<grey>  "..tostring(o.label or k).." type="..tostring(o.type).." members="..tostring(dslCount(o.members)).."\n") end; return end
  if what=="friends" or what=="enemies" then local wanted=(what=="friends" and "friend" or "enemy"); for k,v in pairs(DSL_COLOR_DB.relations.people or {}) do if v==wanted then local p=DSL_COLOR_DB.people[k]; cecho("<grey>  "..tostring((p and p.name) or k).."\n") end end; return end
  if what=="war" or what=="peace" then local wanted=what; for k,v in pairs(DSL_COLOR_DB.relations.orgs or {}) do if v==wanted then local o=DSL_COLOR_DB.orgs[k]; cecho("<grey>  "..tostring((o and o.label) or k).."\n") end end; return end
  if what=="teams" then for team,members in pairs(DSL_COLOR_DB.teams or {}) do cecho("<grey>  "..tostring(team).." members="..tostring(dslCount(members)).."\n") end; return end
  if what=="titles" then
    local rows = {}
    local function add(title, source)
      if title and title:match("^[A-Z]") and not dslIsTitleBlocked(title) then
        rows[title] = rows[title] or {}
        rows[title][source] = true
      end
    end
    for t,_ in pairs(DSL_TITLE_ALIASES or {}) do add(t, "default") end
    for t,_ in pairs(DSL_COLOR_DB.titles or {}) do add(t, "saved") end
    local names = {}
    for t,_ in pairs(rows) do table.insert(names, t) end
    table.sort(names)
    for _,t in ipairs(names) do
      local src = rows[t].saved and rows[t].default and "default,saved" or (rows[t].saved and "saved" or "default")
      cecho("<grey>  "..tostring(t).." <cyan>("..src..")\n")
    end
    return
  end
  if what=="blocked title" or what=="blocked_title" or what=="blocked titles" or what=="title_blocklist" or what=="blocked_titles" then for t,_ in pairs(DSL_COLOR_DB.title_blocklist or {}) do if t:match("^[A-Z]") then cecho("<grey>  "..tostring(t).."\n") end end; return end
  if what=="terms" then for _,term in ipairs(dslSortedTermKeys(DSL_COLOR_DB.terms or {})) do cecho("<grey>  "..tostring(term).." -> <cyan>"..tostring((DSL_COLOR_DB.terms or {})[term]).."\n") end; return end
  if what=="custom_palettes" or what=="custom palettes" then local names={}; for k,_ in pairs(DSL_COLOR_DB.custom_palettes or {}) do table.insert(names,k) end; table.sort(names); for _,name in ipairs(names) do cecho("<grey>  "..name.." -> <cyan>"..dslPaletteSummary((DSL_COLOR_DB.custom_palettes or {})[name]).."\n") end; return end
  if what=="palettes" or what=="palette" then local line=""; for _,pal in ipairs(dslSortedPaletteNames()) do if #line + #pal > 90 then cecho("<grey>  "..line.."\n"); line="" end; if line ~= "" then line=line..", " end; line=line..pal end; if line ~= "" then cecho("<grey>  "..line.."\n") end; return end
  cecho("<yellow>  Unknown list type. Use people, orgs, friends, enemies, war, peace, teams, titles, terms, palettes, custom_palettes.\n")
end

function dslCleanupTitlePeople()
  local removed = {}
  for key, p in pairs(DSL_COLOR_DB.people or {}) do
    local name = p and p.name
    if name and dslIsKnownTitleTerm(name) and not (DSL_COLOR_DB.overrides and DSL_COLOR_DB.overrides[name]) then
      DSL_COLOR_DB.people[key] = nil
      DSL_COLOR_DB.relations.people[key] = nil
      for _, members in pairs(DSL_COLOR_DB.teams or {}) do members[key] = nil end
      for _, org in pairs(DSL_COLOR_DB.orgs or {}) do if org.members then org.members[key] = nil end end
      table.insert(removed, name)
    end
  end
  dslColorSave()
  table.sort(removed)
  cecho("\n<yellow>[DslColors] title-person cleanup removed " .. tostring(#removed) .. " record(s).\n")
  if #removed > 0 then cecho("<grey>  " .. table.concat(removed, ", ") .. "\n") end
end

function dslColorCommand(raw)
  local cmd=dslTrim(raw or "")
  if cmd=="" or cmd=="help" then dslColorHelp(""); return end
  local h=cmd:match("^help%s+(.+)$"); if h then dslColorHelp(h); return end

  local n=cmd:match("^friend%s+([%a'%-]+)$"); if n then dslSetPersonRelation(n,"friend"); return end
  n=cmd:match("^enemy%s+([%a'%-]+)$"); if n then dslSetPersonRelation(n,"enemy"); return end
  n=cmd:match("^neutral%s+([%a'%-]+)$"); if n then dslSetPersonRelation(n,"neutral"); return end
  local o=cmd:match("^war%s+(.+)$"); if o then dslSetOrgRelation(o,"war"); return end
  o=cmd:match("^peace%s+(.+)$"); if o then dslSetOrgRelation(o,"peace"); return end
  o=cmd:match("^neutral%s+org%s+(.+)$"); if o then dslSetOrgRelation(o,"neutral"); return end

  n=cmd:match("^show%s+person%s+([%a'%-]+)$") or cmd:match("^show%s+([%a'%-]+)$"); if n then dslShowPerson(n); return end
  o=cmd:match("^show%s+org%s+(.+)$"); if o then dslShowOrg(o); return end
  local l=cmd:match("^list%s+(.+)$"); if l then dslList(l); return end
  local c=cmd:match("^census%s*(.*)$"); if c~=nil then dslCensus(c); return end

  if cmd=="palettes" or cmd=="list palettes" then dslList("palettes"); return end
  if cmd=="palette" then dslList("palettes"); return end
  if cmd:match("^palette%s+") then dslPaletteCommand(cmd); return end

  local termText, termPalette = dslParseTermCommand(cmd)
  if termText and termPalette then dslSaveCustomTerm(termText, termPalette); return end
  local forgetTerm = cmd:match('^forget%s+term%s+"([^"]+)"$') or cmd:match("^forget%s+term%s+(.+)$")
  if forgetTerm then dslForgetCustomTerm(forgetTerm); return end

  local overrideName, overridePal = cmd:match("^name%s+([%a'%-]+)%s+([%w_]+)$")
  if overrideName and overridePal then
    local pal = dslResolvePaletteName(overridePal)
    if pal then DSL_COLOR_DB.overrides[overrideName] = pal; dslColorSave(); cecho("\n<green>[DslColors] name override saved: "..overrideName.." -> "..pal.."\n") else cecho("\n<red>[DslColors] unknown palette: "..tostring(overridePal).."\n") end
    return
  end

  local ignoreName = cmd:match('^ignore%s+"([^"]+)"$') or cmd:match("^ignore%s+(.+)$")
  if ignoreName then
    ignoreName = dslTrim(ignoreName)
    DSL_COLOR_DB.ignored[ignoreName] = true
    DSL_COLOR_DB.ignored[string.lower(ignoreName)] = true
    DSL_COLOR_DB.people[dslKey(ignoreName)] = nil
    DSL_COLOR_DB.overrides[ignoreName] = nil
    DSL_COLOR_DB.overrides[string.lower(ignoreName)] = nil
    if DSL_COLOR_DB.aliases then DSL_COLOR_DB.aliases[dslKey(ignoreName)] = nil end
    dslColorSave()
    cecho("\n<yellow>[DslColors] ignored: "..ignoreName.."\n")
    return
  end

  local unignoreName = cmd:match('^unignore%s+"([^"]+)"$') or cmd:match("^unignore%s+(.+)$")
  if unignoreName then
    unignoreName = dslTrim(unignoreName)
    DSL_COLOR_DB.ignored[unignoreName] = nil
    DSL_COLOR_DB.ignored[string.lower(unignoreName)] = nil
    DSL_COLOR_DB.ignored[dslKey(unignoreName)] = nil
    dslColorSave()
    cecho("\n<green>[DslColors] unignored: "..unignoreName.."\n")
    return
  end

  local name,team=cmd:match("^team%s+([%a'%-]+)%s+(.+)$")
  if name and team then local key,p=dslEnsurePerson(name); if string.lower(team)=="none" then if p.team and DSL_COLOR_DB.teams[p.team] then DSL_COLOR_DB.teams[p.team][key]=nil end; p.team=nil else p.team=team; DSL_COLOR_DB.teams[team]=DSL_COLOR_DB.teams[team] or {}; DSL_COLOR_DB.teams[team][key]=true end; dslColorSave(); cecho("\n<green>[DslColors] team updated.\n"); return end

  local forgetOverride = cmd:match("^forget%s+name%s+([%a'%-]+)$")
  if forgetOverride then
    local existed = DSL_COLOR_DB.overrides[forgetOverride] ~= nil or DSL_COLOR_DB.overrides[string.lower(forgetOverride)] ~= nil
    DSL_COLOR_DB.overrides[forgetOverride] = nil
    DSL_COLOR_DB.overrides[string.lower(forgetOverride)] = nil
    dslColorSave()
    if existed then cecho("\n<yellow>[DslColors] name override forgotten: "..forgetOverride.."\n") else cecho("\n<yellow>[DslColors] no name override found for: "..forgetOverride.."\n") end
    return
  end

  local forgetPerson=cmd:match("^forget%s+person%s+([%a'%-]+)$")
  if forgetPerson then
    local key=dslKey(forgetPerson)
    local existed = DSL_COLOR_DB.people[key] ~= nil
    DSL_COLOR_DB.people[key]=nil
    if DSL_COLOR_DB.aliases then for alias,target in pairs(DSL_COLOR_DB.aliases) do if alias == key or target == key then DSL_COLOR_DB.aliases[alias] = nil end end end
    DSL_COLOR_DB.relations.people[key]=nil
    for _,members in pairs(DSL_COLOR_DB.teams or {}) do members[key]=nil end
    for _,org in pairs(DSL_COLOR_DB.orgs or {}) do if org.members then org.members[key]=nil end end
    dslColorSave()
    if existed then cecho("\n<yellow>[DslColors] person forgotten: "..forgetPerson.."\n") else cecho("\n<yellow>[DslColors] no person record found for: "..forgetPerson.."\n") end
    return
  end

  local forgetTitle=cmd:match("^forget%s+title%s+(.+)$")
  if forgetTitle then
    forgetTitle = dslTrim(forgetTitle)
    forgetTitle = forgetTitle:match('^"([^"]+)"$') or forgetTitle
    local firstWord, restWords = forgetTitle:match("^(%w+)%s+(.+)$")
    local categoryWords = { royalty=true, royal=true, military=true, political=true, politics=true, religious=true, scholarly=true, craft=true, unknown=true }
    if firstWord and restWords and categoryWords[string.lower(firstWord)] and not dslTitleExistsRaw(forgetTitle) then
      cecho("\n<red>[DslColors] bad forget-title syntax. Use: dslcolor forget title <exact title>\n")
      return
    end
    local lower = string.lower(forgetTitle)
    DSL_COLOR_DB.titles[forgetTitle]=nil
    DSL_COLOR_DB.titles[lower]=nil
    if (DSL_TITLE_ALIASES or {})[forgetTitle] or (DSL_TITLE_ALIASES or {})[lower] then
      dslBlockTitle(forgetTitle)
      dslColorSave()
      cecho("\n<yellow>[DslColors] default title forgotten/blocked: "..forgetTitle.."\n")
    else
      dslUnblockTitle(forgetTitle)
      dslColorSave()
      cecho("\n<yellow>[DslColors] saved title forgotten: "..forgetTitle.."\n")
    end
    return
  end
  if cmd=="cleanup title-people" or cmd=="cleanup-title" or cmd=="cleanup title" then dslCleanupTitlePeople(); return end
  local cat,title=cmd:match("^title%s+([%w_]+)%s+(.+)$")
  if cat and title then
    title = dslTrim(title)
    title = title:match('^"([^"]+)"$') or title
    local map={royalty="title_royalty",military="title_military",political="title_political",politics="title_political",religious="title_religious",scholarly="title_scholarly",craft="title_craft_titles",unknown="title_unknown_titles"}
    local pal=map[string.lower(cat)]
    if pal then
      dslUnblockTitle(title)
      DSL_COLOR_DB.titles[title]=pal
      DSL_COLOR_DB.titles[string.lower(title)]=pal
      local badKey=dslKey(title)
      local removed=false
      if DSL_COLOR_DB.people[badKey] then DSL_COLOR_DB.people[badKey]=nil; removed=true end
      if DSL_COLOR_DB.aliases then for alias,target in pairs(DSL_COLOR_DB.aliases) do if alias == badKey or target == badKey then DSL_COLOR_DB.aliases[alias] = nil end end end
      if DSL_COLOR_DB.relations and DSL_COLOR_DB.relations.people then DSL_COLOR_DB.relations.people[badKey]=nil end
      for _,members in pairs(DSL_COLOR_DB.teams or {}) do members[badKey]=nil end
      for _,org in pairs(DSL_COLOR_DB.orgs or {}) do if org.members then org.members[badKey]=nil end end
      dslColorSave()
      if removed then cecho("\n<green>[DslColors] title saved and old title-as-person record removed: "..title.." ("..cat..")\n") else cecho("\n<green>[DslColors] title saved: "..title.." ("..cat..")\n") end
    else
      cecho("\n<red>[DslColors] bad title category. Use royalty, military, political, religious, scholarly, craft, or unknown.\n")
    end
    return
  end

  n=cmd:match("^killed%s+([%a'%-]+)$"); if n then dslCombatEvent(n,"killed_by_me","manual kill"); return end
  n=cmd:match("^killedby%s+([%a'%-]+)$"); if n then dslCombatEvent(n,"killed_me","manual killedby"); return end
  n=cmd:match("^downed%s+([%a'%-]+)$"); if n then dslCombatEvent(n,"downed_by_me","manual downed"); return end
  n=cmd:match("^downedby%s+([%a'%-]+)$"); if n then dslCombatEvent(n,"downed_me","manual downedby"); return end
  name,note=cmd:match("^combat%s+note%s+([%a'%-]+)%s+(.+)$"); if name and note then dslCombatEvent(name,"note",note); return end
  n=cmd:match("^combat%s+show%s+([%a'%-]+)$"); if n then dslShowPerson(n); return end

  local masterSetting=cmd:match("^(on)$") or cmd:match("^(off)$"); if masterSetting then DSL_COLOR_DB.settings.enabled=(masterSetting=="on"); dslColorSave(); cecho("\n<green>[DslColors] enabled="..tostring(DSL_COLOR_DB.settings.enabled).."\n"); return end
  local setting=cmd:match("^echo%s+(on)$") or cmd:match("^echo%s+(off)$"); if setting then DSL_COLOR_DB.settings.echo_updates=(setting=="on"); dslColorSave(); cecho("\n<green>[DslColors] echo_updates="..tostring(DSL_COLOR_DB.settings.echo_updates).."\n"); return end
  if cmd=="test" then cecho("\n<cyan>[DslColors v1.0 RELEASE] runtime test\n"); dslPrintKV("data_path",DSL_COLOR_DATA_PATH); dslPrintKV("known_people",dslCount(DSL_COLOR_DB.people)); dslPrintKV("known_orgs",dslCount(DSL_COLOR_DB.orgs)); dslPrintKV("race_aliases",dslCount(DSL_RACE_ALIASES)); dslPrintKV("class_aliases",dslCount(DSL_CLASS_ALIASES)); dslPrintKV("title_aliases",dslCount(DSL_TITLE_ALIASES)); dslPrintKV("blocked_titles",dslCount(DSL_COLOR_DB.title_blocklist)); dslPrintKV("person_aliases",dslCount(DSL_COLOR_DB.aliases)); dslPrintKV("custom_terms",dslCount(DSL_COLOR_DB.terms)); dslPrintKV("custom_palettes",dslCount(DSL_COLOR_DB.custom_palettes)); if DSL_COLOR_LAST_LOAD then dslPrintKV("loaded_existing_file", tostring(DSL_COLOR_LAST_LOAD.ok)) end; if DSL_COLOR_LAST_SAVE then dslPrintKV("last_save_ok", tostring(DSL_COLOR_LAST_SAVE.ok)) end; cecho("<green>  alias/core is working.\n"); return end
  if cmd=="savepath" then cecho("\n<cyan>[DslColors] save path: "..DSL_COLOR_DATA_PATH.."\n"); return end
  if cmd=="save" then local ok,err=dslColorSave(); if ok then cecho("\n<green>[DslColors] saved to "..DSL_COLOR_DATA_PATH.."\n") else cecho("\n<red>[DslColors] save failed: "..tostring(err).."\n") end; return end
  if cmd=="reload" then dslColorLoad(); cecho("\n<green>[DslColors] reloaded.\n"); return end
  cecho("\n<red>[DslColors] Unknown command. Use: dslcolor help commands\n")
end

function dslColorInstallRuntimeAlias()
  if DSL_COLOR_RUNTIME_ALIAS_ID then pcall(killAlias, DSL_COLOR_RUNTIME_ALIAS_ID) end
  DSL_COLOR_RUNTIME_ALIAS_ID = tempAlias("^dslcolor(?:\\s+(.*))?$", [[dslColorCommand(matches[2] or "")]])
end

-- Final init after every function exists.
dslColorLoad()
dslColorInstallRuntimeAlias()
cecho("\n<green>[DslColors v1.0 RELEASE] loaded. Use: dslcolor test\n")
